// Handle both possible data shapes from n8n webhook v2
const raw = $input.first().json;
const body = raw.body || raw;
const chatId = body.chatId || raw.chatId || '';

function esc(v) {
  if (!v) return null;
  return "'" + String(v).replace(/'/g, "''") + "'";
}

const name = esc(body.customer_name) || "'Nenurodyta'";
const phone = esc(body.customer_phone) || "'Nenurodyta'";
const date = body.event_date ? esc(body.event_date) : 'CURRENT_DATE';
const time = body.event_time ? esc(body.event_time) + '::time' : 'NULL';
const pickup = body.pickup_time ? esc(body.pickup_time) + '::time' : 'NULL';
const addr = esc(body.delivery_address) || "''";
const city = esc(body.city) || "''";
const price = body.price ? Number(body.price) || 0 : 0;
const notes = esc(body.notes) || "''";

const sql = `
WITH contact_upsert AS (
  INSERT INTO batutynas.contacts (name, phone, source)
  VALUES (${name}, ${phone}, 'Telegram')
  ON CONFLICT (phone) DO UPDATE SET name = EXCLUDED.name
  RETURNING id
),
new_booking AS (
  INSERT INTO batutynas.bookings (
    contact_id, event_date, event_time, pickup_time,
    delivery_address, city, status, price, notes, entry_source
  )
  SELECT
    cu.id,
    ${date},
    ${time},
    ${pickup},
    ${addr},
    ${city},
    'Confirmed',
    ${price},
    ${notes},
    'Telegram'
  FROM contact_upsert cu
  RETURNING id
)
SELECT id FROM new_booking;
`;

return [{ json: { chatId, sql, customerName: body.customer_name || 'Klientas' } }];

